    'books.label': 'Publications',
    'books.title': "Children's books",
    'books.subtitle': 'Illustrated stories for little girls — published under a pen name, with love and intention.',
    'books.pen-name': '✍️ Published under the name Daisy Harper Gray Lane — Visit the site →',
    'books.cover.ph': 'Add cover',
    'books.series.label': 'Series — Women who changed the world',
    'books.series.title': 'Brilliant Women, Remarkable Stories — published in English',
    'books.series.desc': "Eight portraits of extraordinary women, told for children. Scientists, adventurers, resisters, queens — figures who shook their era and whose stories deserve to be passed on from the very first pages. Each book, a life. Each life, a lesson.",
    'books.series.tag': '📚 8 books · Illustrated · Under pen name',
    'books.about.title': 'Why these books?',
    'books.about.desc': "Because little girls deserve stories that look like them — brave heroines, colorful worlds, messages that stay. These eight women changed the world. These eight books are here to remember them.",
    'book.ada.name': 'Ada Lovelace', 'book.ada.era': '1815 – 1852 · Mathematics',
    'book.ada.desc': "She wrote the first algorithm in history — a century before the computer was invented. Ada refused to be told what a woman couldn't do.",
    'book.marie.name': 'Marie Curie', 'book.marie.era': '1867 – 1934 · Physics & Chemistry',
    'book.marie.desc': "Two Nobel Prizes. One person. Marie discovered radioactivity in a lab she was denied access to, in an era that closed every door on her. She opened them all.",
    'book.rosa.name': 'Rosa Parks', 'book.rosa.era': '1913 – 2005 · Civil Rights',
    'book.rosa.desc': "On December 1st, 1955, Rosa refused to give up her seat on a bus. That simple act sparked a movement. You don't need to shout to change the world — sometimes you just need to stay seated.",
    'book.amelia.name': 'Amelia Earhart', 'book.amelia.era': '1897 – 1937 · Aviation',
    'book.amelia.desc': "The first woman to fly solo across the Atlantic. Amelia looked at the sky the way others look at the ground — as something that belonged to her.",
    'book.cleo.name': 'Cleopatra', 'book.cleo.era': '69 – 30 BC · Egypt',
    'book.cleo.desc': "Queen of Egypt at 18, polyglot, strategist, philosopher. Cleopatra wasn't just beautiful — she was the most powerful and learned woman of her time.",
    'book.saca.name': 'Sacagawea', 'book.saca.era': '~1788 – 1812 · Exploration',
    'book.saca.desc': "Guide for the Lewis & Clark expedition, she crossed the American wilderness with a newborn on her back. Without her, one of history's greatest explorations would have failed.",
    'book.tag.science': 'Science & Innovation', 'book.tag.courage': 'Courage & Justice',
    'book.tag.adventure': 'Adventure & Pioneer', 'book.tag.power': 'Power & Diplomacy',
    'book.tag.art': 'Art & Resilience', 'book.tag.literature': 'Writing & Emancipation',
    'book.frida.name': 'Frida Kahlo', 'book.frida.era': '1907 – 1954 · Art',
    'book.frida.desc': "She painted her pain and her strength in blazing colours. Frida turned every ordeal into a masterpiece — and the world never forgot her gaze.",
    'book.zelda.name': 'Zelda Fitzgerald', 'book.zelda.era': '1900 – 1948 · Writing & Art',
    'book.zelda.desc': "Dancer, writer, painter — Zelda lived for too long in the shadow of a great name. She was, in truth, a light entirely her own.",
    'book.buy': 'Buy', 'book.buy.soon': 'Coming soon',

    'finance.tab.seminar': 'Finance Fundamentals',
    'finance.tab.notchwork': 'NotchWork — Rating',
    'nw.title': 'NotchWork',
    'nw.desc': "AI-powered multi-agency shadow rating platform — Claude Sonnet 4.5 with extended thinking. The S&P shadow rating (full methodology, 18 PDFs ingested in 1,144 RAG chunks) is the primary engine, cross-checked by parallel high-level Moody's (44 sector scorecards verbatim) and Fitch (58 sector navigators verbatim) shadow ratings. Silent 3-way reconciliation in the background when any pair gap exceeds 3 notches. Upload an annual report, get three parallel shadow ratings and a full IB memo. Access via user account (monthly subscription).",
    'nw.stat.agencies': "Parallel agencies (S&P + Moody's + Fitch)",
    'nw.stat.scorecards': "Moody's scorecards + Fitch navigators",
    'nw.stat.time': "Annual report → 3 ratings",
    'nw.stat.chunks': "S&P · Moody's Chunks", 'nw.stat.steps': 'Steps', 'nw.stat.slides': 'IB memo slides',
    'nw.f1.title': "Triple S&P + Moody's + Fitch engines",
    'nw.f1.desc': "Claude Sonnet 4.5 applies the S&P framework (CICRA → BRP × FRP → Anchor → Modifiers → ICR) as the primary engine, cross-checked in parallel by Moody's sector scorecards and Fitch's Sector Navigator. Structured JSON output with strengths, challenges, sensitivities, IB-style narrative.",
    'nw.f2.title': "Verbatim methodology ingestion",
    'nw.f2.desc': "18 S&P PDFs + 44 Moody's scorecards (Regulated Networks, Utilities, Integrated O&G, Auto, Telecom, Pharma, REITs, Steel…) + 58 Fitch sector navigators (Sector Navigators Addendum, 264 pages) — all extracted word-for-word from official publications. RAG via Supabase pgvector + prompt caching for 10× input cost reduction.",
    'nw.f3.title': "3-way cross-agency reconciliation",
    'nw.f3.desc': "Unified S&P ↔ Moody's ↔ Fitch scale. If any pair gap exceeds 2 notches (rare in practice), all three engines re-run automatically with the other agencies' ratings in context — methodology / sector sanity-check included. The user doesn't see this check, just the final ratings.",
    'nw.f4.title': "IB memo + Beyond the Big 3",
    'nw.f4.desc': "PowerPoint memo export (cover, strengths/challenges, CICRA/BRP, Anchor matrix, triple-column financials, Moody's scorecard, Fitch navigator, conclusion). Plus a 40+ slide reference deck on the global rating ecosystem — ECAI, NAIC, USPP, regional agencies.",
